CREATE OR REPLACE FUNCTION public.timesheets_invalidate_prevalidation_on_change()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
declare
  v_tv_status public.validation_status_enum;
  v_tv_pre_validated boolean;
  v_tv_hr_request_id text;
  v_tv_hr_request_source public.reference_source_enum;

  v_changed boolean := false;

  -- DAILY change flags
  v_daily_changed_worked boolean := false;
  v_daily_changed_break boolean := false;
  v_daily_changed_refnum boolean := false;
  v_daily_changed_dayrefs boolean := false;

  -- WEEKLY change flags
  v_weekly_changed_sched boolean := false;
  v_weekly_changed_refnum boolean := false;
  v_weekly_changed_dayrefs boolean := false;
  v_weekly_changed_units_week boolean := false;
  v_weekly_changed_units_per_day boolean := false;

  v_ignore_daily_ref_autoset boolean := false;
begin
  if tg_op <> 'UPDATE' then
    return new;
  end if;

  -- Only apply to current row updates
  if coalesce(new.is_current, false) is not true then
    return new;
  end if;

  -- If the old row was not current, do not invalidate (avoid version-rotation noise)
  if coalesce(old.is_current, false) is not true then
    return new;
  end if;

  -- Load current validation row (if any)
  select
    tv.status,
    coalesce(tv.pre_validated, false),
    tv.hr_request_id,
    tv.hr_request_source
  into
    v_tv_status,
    v_tv_pre_validated,
    v_tv_hr_request_id,
    v_tv_hr_request_source
  from public.timesheet_validations tv
  where tv.timesheet_id = new.timesheet_id
  limit 1;

  if not found then
    return new;
  end if;

  -- Only invalidate when validation was previously "good" OR pre_validated was set
  if not (
    v_tv_pre_validated is true
    or v_tv_status = 'VALIDATION_OK'::public.validation_status_enum
    or v_tv_status = 'OVERRIDDEN'::public.validation_status_enum
  ) then
    return new;
  end if;

  -- ─────────────────────────────────────────────
  -- Determine whether validation-relevant truth changed
  -- ─────────────────────────────────────────────
  if new.sheet_scope = 'DAILY'::public.timesheet_scope_enum then
    v_daily_changed_worked :=
      (new.worked_start_iso is distinct from old.worked_start_iso)
      or (new.worked_end_iso is distinct from old.worked_end_iso);

    v_daily_changed_break :=
      (new.break_start_iso is distinct from old.break_start_iso)
      or (new.break_end_iso is distinct from old.break_end_iso)
      or (new.break_minutes is distinct from old.break_minutes);

    v_daily_changed_refnum :=
      (new.reference_number is distinct from old.reference_number);

    v_daily_changed_dayrefs :=
      (new.day_references_json is distinct from old.day_references_json);

    -- Special-case: DAILY reference_number auto-set to imported HR request id
    -- Do NOT invalidate if the ONLY relevant change is reference_number and it matches the imported hr_request_id.
    if v_daily_changed_refnum is true
       and v_daily_changed_worked is false
       and v_daily_changed_break is false
       and v_daily_changed_dayrefs is false
       and v_tv_hr_request_source = 'IMPORTED'::public.reference_source_enum
       and v_tv_hr_request_id is not null
       and new.reference_number is not distinct from v_tv_hr_request_id
    then
      v_ignore_daily_ref_autoset := true;
    end if;

    v_changed :=
      (v_daily_changed_worked or v_daily_changed_break or v_daily_changed_dayrefs or v_daily_changed_refnum)
      and v_ignore_daily_ref_autoset is false;

  elsif new.sheet_scope = 'WEEKLY'::public.timesheet_scope_enum then
    v_weekly_changed_sched :=
      (new.actual_schedule_json is distinct from old.actual_schedule_json);

    v_weekly_changed_refnum :=
      (new.reference_number is distinct from old.reference_number);

    v_weekly_changed_dayrefs :=
      (new.day_references_json is distinct from old.day_references_json);

    v_weekly_changed_units_week :=
      (new.additional_units_week is distinct from old.additional_units_week);

    v_weekly_changed_units_per_day :=
      (new.additional_units_per_day is distinct from old.additional_units_per_day);

    v_changed :=
      v_weekly_changed_sched
      or v_weekly_changed_refnum
      or v_weekly_changed_dayrefs
      or v_weekly_changed_units_week
      or v_weekly_changed_units_per_day;
  else
    return new;
  end if;

  if v_changed is not true then
    return new;
  end if;

  -- ─────────────────────────────────────────────
  -- Invalidate pre-validation + force re-validation
  -- ─────────────────────────────────────────────
  update public.timesheet_validations tvu
     set status = 'PENDING'::public.validation_status_enum,
         pre_validated = false,
         validated_at_utc = null,
         reason_code = 'TIMESHEET_CHANGED',
         updated_at = now()
   where tvu.timesheet_id = new.timesheet_id;

  return new;
end;
$function$;

create or replace function private._candidate_qr_pack_ready_notification_v1()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, public, private, pg_temp
as $function$
declare
  v_notification jsonb;
begin
  if (not private._candidate_feature_enabled_current_v1('candidate_route_confirmation')
       and not private._candidate_office_service_context_valid_v1(null,null,'ROUTE_CONFIRM'))
     or new.candidate_submission_route_intent is distinct from 'PAPER'
     or new.sheet_scope is distinct from 'WEEKLY'::public.timesheet_scope_enum
     or upper(coalesce(new.document_state::text,''))<>'READY'
     or upper(coalesce(new.qr_status::text,'')) not in ('PENDING','SENT','READY') then
    return new;
  end if;
  if new.current_document_version_id is null or not exists(
    select 1 from public.invoice_document_versions document_version
    where document_version.id=new.current_document_version_id
      and document_version.entity_type='TIMESHEET'
      and document_version.entity_id=new.timesheet_id
      and upper(document_version.status)='READY'
  ) then
    return new;
  end if;
  if exists(
    select 1
    from public.candidate_submission_workflows workflow
    where workflow.route='PAPER'
      and workflow.state='AWAITING_PAPER_RETURN'
      and (workflow.target_timesheet_id=new.timesheet_id
        or workflow.anchor_timesheet_id=new.timesheet_id)
  ) then
    return new;
  end if;
  v_notification:=private._timesheet_route_resubmission_notifications_v1(
    new.timesheet_id,new.timesheet_id,new.version,'ALLOW_QR_AGAIN',now()
  );
  new.candidate_submission_route_intent:=null;
  return new;
end;
$function$;

create or replace function private._timesheet_authorisation_overlap_trg_v1()
returns trigger language plpgsql volatile security definer
set search_path='public','private','pg_temp' as $function$
declare
  v_candidate_id uuid;
  v_candidate_count integer:=0;
  v_fin_schedule jsonb;
  v_fin_start timestamptz;
  v_fin_end timestamptz;
  v_interval_count integer:=0;
begin
  if new.authorised_at_server is null then return new; end if;
  if tg_op='UPDATE' and old.authorised_at_server is not distinct from new.authorised_at_server then
    return new;
  end if;

  select f.actual_schedule_json,f.worked_start_iso,f.worked_end_iso
  into v_fin_schedule,v_fin_start,v_fin_end
  from public.timesheets_financials f
  where f.timesheet_id=new.timesheet_id and f.is_current=true
  order by f.updated_at desc nulls last,f.created_at desc nulls last,f.id desc
  limit 1;

  select count(*)::integer into v_interval_count
  from private._timesheet_work_intervals_v1(
    '{}'::jsonb,COALESCE(new.actual_schedule_json,v_fin_schedule),
    COALESCE(new.worked_start_iso,v_fin_start),COALESCE(new.worked_end_iso,v_fin_end)
  );
  if v_interval_count=0 then return new; end if;

  with candidate_ids as (
    select w.candidate_id
    from public.candidate_submission_workflows w
    where w.id=new.candidate_workflow_id
    union
    select f.candidate_id
    from public.timesheets_financials f
    where f.timesheet_id=new.timesheet_id and f.is_current=true and f.candidate_id is not null
    union
    select c.candidate_id from public.contracts c where c.id=new.contract_id and c.candidate_id is not null
    union
    select c.id from public.candidates c
    where c.key_norm is not null and c.key_norm=new.occupant_key_norm
  )
  select count(*)::integer,min(candidate_id::text)::uuid
  into v_candidate_count,v_candidate_id from candidate_ids;

  if v_candidate_count<>1 or v_candidate_id is null then
    raise exception using
      errcode='PT409',
      message='TIMESHEET_CANDIDATE_IDENTITY_REQUIRED_FOR_OVERLAP_CHECK';
  end if;

  perform private._timesheet_cross_record_overlap_assert_v1(
    v_candidate_id,'{}'::jsonb,COALESCE(new.actual_schedule_json,v_fin_schedule),
    COALESCE(new.worked_start_iso,v_fin_start),COALESCE(new.worked_end_iso,v_fin_end),
    new.candidate_workflow_id,new.timesheet_id,new.booking_id
  );
  return new;
end;$function$;

create or replace function private._timesheet_settings_authority_before_v1()
returns trigger
language plpgsql
volatile
security definer
set search_path = pg_catalog, public, private, extensions, pg_temp
as $function$
declare
  v_contract public.contracts%rowtype;
  v_snapshot jsonb;
  v_client_id uuid;
  v_relevant_date date;
begin
  if tg_op='UPDATE' and old.settings_authority_json<>'{}'::jsonb then
    new.settings_authority_json:=old.settings_authority_json;
    new.settings_authority_version:=old.settings_authority_version;
    new.settings_authority_fingerprint:=old.settings_authority_fingerprint;
    new.settings_authority_resolved_at:=old.settings_authority_resolved_at;
    return new;
  end if;
  if new.sheet_scope<>'WEEKLY'::public.timesheet_scope_enum then
    if tg_op='INSERT' then
      new.settings_authority_json:='{}'::jsonb;
      new.settings_authority_version:=null;
      new.settings_authority_fingerprint:=null;
      new.settings_authority_resolved_at:=null;
      return new;
    end if;
    select tf.client_id into v_client_id
    from public.timesheets_financials tf
    where tf.timesheet_id=new.timesheet_id and tf.is_current=true
      and tf.processed_at_utc is not null
    order by tf.computed_at_utc desc nulls last,tf.updated_at desc,tf.id desc
    limit 1;
    if not found then
      new.settings_authority_json:='{}'::jsonb;
      new.settings_authority_version:=null;
      new.settings_authority_fingerprint:=null;
      new.settings_authority_resolved_at:=null;
      return new;
    end if;
    v_relevant_date:=coalesce(
      (new.worked_start_iso at time zone 'Europe/London')::date,
      (new.scheduled_start_iso at time zone 'Europe/London')::date,
      new.week_ending_date
    );
    v_snapshot:=private._contract_settings_effective_core_v1(
      v_client_id,new.contract_id,v_relevant_date,'DAILY',null
    );
    new.settings_authority_json:=v_snapshot;
    new.settings_authority_version:='CONTRACT_SETTINGS_AUTHORITY_V1';
    new.settings_authority_fingerprint:=v_snapshot->>'authority_fingerprint';
    new.settings_authority_resolved_at:=(v_snapshot->>'resolved_at_utc')::timestamptz;
    return new;
  end if;
  if new.contract_id is null then
    new.settings_authority_json:='{}'::jsonb;
    new.settings_authority_version:=null;
    new.settings_authority_fingerprint:=null;
    new.settings_authority_resolved_at:=null;
    return new;
  end if;
  select * into v_contract from public.contracts c where c.id=new.contract_id;
  if not found then return new; end if;
  v_snapshot:=private._contract_settings_effective_core_v1(
    v_contract.client_id,v_contract.id,new.week_ending_date,'WEEKLY',null
  );
  new.settings_authority_json:=v_snapshot;
  new.settings_authority_version:='CONTRACT_SETTINGS_AUTHORITY_V1';
  new.settings_authority_fingerprint:=v_snapshot->>'authority_fingerprint';
  new.settings_authority_resolved_at:=(v_snapshot->>'resolved_at_utc')::timestamptz;
  return new;
end
$function$;

