do $weekly_source_settings_admin_acl$
declare
  v_signature text;
begin
  foreach v_signature in array array[
    'public.weekly_source_client_settings_get_v1(jsonb)',
    'public.weekly_source_client_settings_save_atomic_v1(jsonb)',
    'public.weekly_source_contract_settings_get_v1(jsonb)',
    'public.weekly_source_contract_settings_save_atomic_v1(jsonb)',
    'public.weekly_source_global_settings_get_v1(jsonb)',
    'public.weekly_source_global_settings_save_atomic_v1(jsonb)',
    'public.weekly_source_source_groups_get_v1(jsonb)',
    'public.weekly_source_source_group_save_atomic_v1(jsonb)'
  ]
  loop
    -- Miget restores the repository's audited logical postgres owner as the
    -- provider service owner, so dynamic owner statements must use the
    -- current release role rather than attempting SET ROLE postgres.
    execute 'alter function '||v_signature||' owner to current_user';
    execute 'revoke all on function '||v_signature||' from public,anon,authenticated';
    execute 'grant execute on function '||v_signature||' to service_role';
  end loop;
end;
$weekly_source_settings_admin_acl$;

do $acl$
declare v_signature text;
begin
  foreach v_signature in array array[
    'private.bpay_next_source_current_inventory_v1(uuid,integer,uuid,uuid,uuid,date,date)',
    'private.bpay_next_source_current_lock_recheck_v1(uuid)',
    'private.bpay_next_source_current_lock_release_v1(uuid)',
    'private.bpay_next_source_current_lock_inventory_v1(uuid,integer,uuid,uuid,uuid,date,date)',
    'private.bpay_next_source_current_observe_v1(uuid,uuid,uuid)',
    'private.bpay_next_source_current_observation_v1(uuid)',
    'private.bpay_next_source_current_observe_expense_row_v1(uuid,uuid)',
    'private.bpay_next_source_current_publish_revision_v1(uuid)',
    'private.bpay_next_source_current_apply_correction_v1(uuid)'
  ] loop
    execute format('alter function %s owner to %I',v_signature,current_user);
    execute format('revoke all on function %s from public,anon,authenticated,service_role',v_signature);
  end loop;
end $acl$;

selectedSchemaStatements.definition:
create table public.candidates_tombstones (
  id uuid not null,
  deleted_rev bigint not null,
  deleted_at timestamp with time zone not null
);

create table public.clients_tombstones (
  id uuid not null,
  deleted_rev bigint not null,
  deleted_at timestamp with time zone not null
);

create table public.timesheet_financial_retention (
  timesheet_id uuid not null,
  first_retained_at_utc timestamp with time zone not null
);

create table if not exists public.app_change_counters (
  entity_key text primary key,
  seq bigint not null default 0,
  updated_at timestamptz not null default now()
);

alter table public.candidates
  drop column if exists revolut_counterparty_id,
  drop column if exists revolut_counterparty_account_id;

alter table public.client_settings
  add column if not exists reversal_complete_financials_date
    public.correction_financials_date_basis_enum;

alter table public.client_settings
  add column if not exists reversal_replacement_financials_date
    public.correction_financials_date_basis_enum;

alter table public.contracts
  add column if not exists send_ts_queries_to_different_email boolean not null default false,
  add column if not exists ts_queries_alt_email_address text;

alter table public.client_settings
  add column if not exists healthroster_import_auto_authorise boolean not null default true,
  add column if not exists nhsp_import_auto_authorise boolean not null default false;

alter table public.contracts
  add column if not exists healthroster_import_auto_authorise_override boolean,
  add column if not exists nhsp_import_auto_authorise_override boolean;

ALTER TABLE public.app_change_counters
  ADD COLUMN IF NOT EXISTS scope_change_generation bigint,
  ADD COLUMN IF NOT EXISTS scope_change_tx_token uuid;

ALTER TABLE public.banking_pay_workbench_jobs
  ADD COLUMN IF NOT EXISTS scope_change_generation bigint,
  ADD COLUMN IF NOT EXISTS scope_change_tx_token uuid;

alter table public.timesheet_evidence
  add column if not exists document_role text,
  add column if not exists candidate_component_id uuid;

alter table public.timesheet_evidence
  alter column document_role set default 'SOURCE_EVIDENCE',
  alter column document_role set not null;

alter table public.timesheets
  add constraint timesheets_candidate_workflow_generation_ck check (
    candidate_workflow_generation is null or candidate_workflow_generation > 0
  ),
  add constraint timesheets_candidate_workflow_pair_ck check (
    (candidate_workflow_id is null and candidate_workflow_generation is null)
    or (candidate_workflow_id is not null and candidate_workflow_generation is not null)
  );

ALTER TABLE public.banking_pay_workbench_jobs
  DROP CONSTRAINT bpay_wb_jobs_private_stage_cursor_chk,
  DROP CONSTRAINT bpay_wb_jobs_build_identity_chk;

alter table public.candidate_submission_workflows
  add column if not exists creation_request_sha256 bytea,
  add column if not exists creation_identity_json jsonb;

alter table public.contracts
  add column if not exists timesheet_break_entry_mode
    public.timesheet_break_entry_mode_enum;

alter table public.weekly_source_group_clients
  add constraint weekly_source_group_clients_no_overlap
  exclude using gist (
    client_id with =,
    daterange(valid_from,coalesce(valid_to,'infinity'::date),'[]') with &&
  );

alter table public.weekly_final_source_correction_sessions
  add constraint weekly_final_source_correction_sessions_upload_fk
  foreign key (replacement_correction_upload_id) references public.weekly_source_uploads(id) on delete restrict;

alter table public.weekly_source_billing_movements
  add constraint weekly_source_billing_movements_prior_fk
  foreign key (prior_movement_id) references public.weekly_source_billing_movements(id) on delete restrict;

alter table public.weekly_source_cycles
  add constraint weekly_source_cycles_current_upload_fk
  foreign key (current_complete_upload_id) references public.weekly_source_uploads(id) on delete restrict;

alter table public.weekly_source_cycles
  add constraint weekly_source_cycles_current_final_fk
  foreign key (current_final_revision_id) references public.weekly_source_final_revisions(id) on delete restrict;

alter table public.weekly_source_cycles
  add constraint weekly_source_cycles_current_publication_fk
  foreign key (current_projection_publication_id) references public.weekly_source_projection_publications(id) on delete restrict;

alter table public.weekly_source_report_scopes
  add constraint weekly_source_report_scopes_current_upload_fk
  foreign key (current_complete_upload_id) references public.weekly_source_uploads(id) on delete restrict;

CREATE TABLE private.bpay_clock_families_v1 (
  id uuid DEFAULT gen_random_uuid() NOT NULL,
  booking_id text NOT NULL
);

CREATE TABLE private.bpay_clock_rows_v1 (
  timesheet_id uuid NOT NULL,
  family_id uuid NOT NULL,
  authorisation_at timestamp with time zone,
  consumed_at timestamp with time zone
);

alter table public.weekly_source_cycles
  add constraint weekly_source_cycles_group_week_client_uq
  unique nulls not distinct (source_group_id,finalisation_week_ending,scope_client_id);

create table private.bpay_next_source_current_snapshots (
  snapshot_line_id uuid primary key references public.weekly_source_final_snapshot_lines(id),
  scope_id uuid not null references private.bpay_next_source_current_scopes(id),
  work_event_id uuid not null references public.weekly_work_events(id),
  movement_id uuid not null references public.weekly_source_billing_movements(id)
);

create table private.bpay_next_snooze_request (
  request_id uuid primary key references private.bpay_next_command(id), actor_id uuid not null references public.tms_users(id),
  action text not null check(action in ('SNOOZE_WARNING_ACK_ISSUE','SNOOZE_SET','SNOOZE_CLEAR')),
  request_body jsonb not null, result_body jsonb not null,
  created_at_utc timestamptz not null default pg_catalog.clock_timestamp()
);

create table private.candidate_notification_dismissal_owners (
  notification_id uuid primary key references public.candidate_notifications(id) on delete cascade,
  operation_id uuid not null references private.candidate_notification_operations(id) on delete restrict,
  dismissed_at_utc timestamptz not null
);

ALTER TABLE public.candidates
  ADD COLUMN IF NOT EXISTS tms_ref_num integer
  GENERATED ALWAYS AS (
    NULLIF(regexp_replace(tms_ref, '[^0-9]', '', 'g'), '')::integer
  ) STORED;

ALTER TABLE public.timesheets
  ADD CONSTRAINT timesheets_candidate_hint_text_is_object
  CHECK (
    candidate_hint_text IS NULL
    OR jsonb_typeof(candidate_hint_text) = 'object'
  );
